			var continuationDiffs int
			if err := selected.db.QueryRowContext(ctx,
				"SELECT COUNT(*) FROM entity_mutations WHERE run_id=$1 AND caused_by_event=$2", runID, completionID).Scan(&continuationDiffs); err != nil {
				t.Fatal(err)
